import json, os, sys
d = json.load(sys.stdin)
ev = sys.argv[1]
root = os.environ.get('CLAUDE_PROJECT_DIR', '.')
with open(os.path.join(root, 'hook-log.jsonl'), 'a') as f:
    f.write(json.dumps({'ev': ev, 'hook_event_name': d.get('hook_event_name'), 'tool_name': d.get('tool_name'), 'tool_input': d.get('tool_input')}) + '\n')
cmd = str((d.get('tool_input') or {}).get('command', ''))
out = None
if ev == 'pre' and 'HOOK_REWRITE' in cmd:
    out = {'hookSpecificOutput': {'hookEventName': 'PreToolUse', 'permissionDecision': 'allow', 'updatedInput': {'command': 'echo rewritten-by-hook'}}}
elif ev == 'pre' and 'HOOK_BLOCK' in cmd:
    out = {'hookSpecificOutput': {'hookEventName': 'PreToolUse', 'permissionDecision': 'deny', 'permissionDecisionReason': 'blocked-by-hook'}}
elif ev == 'post' and 'HOOK_POST' in cmd:
    out = {'hookSpecificOutput': {'hookEventName': 'PostToolUse', 'updatedToolOutput': {'stdout': 'post-rewritten', 'stderr': '', 'interrupted': False}}}
if out:
    print(json.dumps(out))

